insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_6_v1'
from (values
('128.7.b.1.A',3,'A listener''s crossed arms and frown are examples of:','["non-verbal messages", "spelling errors", "punctuation marks", "written messages"]'::jsonb,0,'Body language is a non-verbal message a listener can interpret.','original'),
('128.7.b.1.A',3,'To interpret a speaker''s message fully, a listener pays attention to words and also to:','["the room''s paint", "tone of voice and body language", "the clock", "the seating chart"]'::jsonb,1,'Verbal and non-verbal cues work together.','original'),
('128.7.b.1.B',3,'A coach says: stretch, jog two laps, then drink water. Following multiple action steps means:','["doing only the last one", "skipping the water", "doing each action in the order given", "doing them in any order, or none"]'::jsonb,2,'Multi-step directions are followed in sequence.','original'),
('128.7.b.1.B',3,'To restate multi-step directions accurately, a listener can:','["write nothing and hope", "repeat only the first word", "ask no questions", "summarize each step in sequence"]'::jsonb,3,'Restating each step shows understanding.','original'),
('128.7.b.1.C',3,'An organized oral presentation has:','["a clear opening, body and closing", "no main point", "random order of ideas", "only questions"]'::jsonb,0,'Organization helps listeners follow.','original'),
('128.7.b.1.C',3,'Enunciation means:','["speaking as fast as possible", "pronouncing words clearly", "using only whispers", "speaking as loudly as possible"]'::jsonb,1,'Enunciation is clear pronunciation.','original'),
('128.7.b.1.D',2,'In a group plan with shared responsibilities, each member:','["does everything", "does nothing", "has a role and a task to finish", "waits for others"]'::jsonb,2,'Shared plans assign roles.','original'),
('128.7.b.1.D',3,'If a teammate misses a deadline in a shared plan, a good response is to:','["finish the whole project alone and complain", "ignore it", "quit the group", "talk with the teammate and adjust the plan"]'::jsonb,3,'Collaboration means communicating and adjusting.','original'),
('128.7.b.10.A',3,'An author writes an article explaining how vaccines work. The author''s purpose and message are best described as:','["to inform readers about how vaccines protect people", "to hide the facts", "to sell a product", "to entertain with a silly story"]'::jsonb,0,'Explanatory articles inform.','original'),
('128.7.b.10.A',3,'The message of a text is:','["the title only", "the main point or lesson the author wants readers to take away", "the author''s address", "the number of paragraphs"]'::jsonb,1,'A message is the takeaway.','original'),
('128.7.b.10.B',3,'An author uses chronological structure for a biography to:','["hide the dates", "compare two unrelated people", "show how events in a life unfolded over time", "list vocabulary"]'::jsonb,2,'Text structure supports the author''s purpose.','original'),
('128.7.b.10.B',3,'A problem-and-solution structure in an editorial helps persuade readers by:','["listing random facts", "removing all evidence", "making the topic confusing", "showing why a change is needed"]'::jsonb,3,'Structure supports persuasion.','original'),
('128.7.b.10.C',3,'An inset in a magazine article is used to:','["highlight a related fact or story", "replace the headline", "repeat the page number", "hide the author"]'::jsonb,0,'Insets add focused extra information.','original'),
('128.7.b.10.C',3,'An author''s use of boldface for key terms helps readers:','["ignore the text", "locate important vocabulary", "count the words", "skip the chapter"]'::jsonb,1,'Print features direct attention to key terms.','original'),
('128.7.b.10.D',3,'Which is an example of imagery?','["Bread is food.", "The bread was there.", "The scent of fresh bread drifted through the warm kitchen.", "He ate."]'::jsonb,2,'Imagery appeals to the senses.','original'),
('128.7.b.10.E',3,'In a story with a first-person narrator, the narrator is:','["not in the story at all", "the author''s editor", "an outside voice using he and she", "a character who tells events using I"]'::jsonb,3,'First-person narrators take part in the story.','original'),
('128.7.b.10.E',3,'A third-person limited narrator tells the story:','["from outside, focusing on one character''s thoughts", "without any characters", "with the pronoun I", "by addressing the reader as you"]'::jsonb,0,'Limited narrators focus on a single character''s view.','original'),
('128.7.b.10.F',3,'One author writes a rainstorm scene with short, tense sentences and another with flowing, calm ones. These differences show:','["different spellings", "each author''s voice", "different fonts", "different page numbers"]'::jsonb,1,'Sentence style helps create voice.','original'),
('128.7.b.10.F',3,'A humorous voice often uses:','["only dates and numbers", "formal legal terms", "playful word choice and exaggeration", "no adjectives"]'::jsonb,2,'Humor shows in word choice.','original'),
('128.7.b.10.G',3,'A stereotype is:','["a proven fact about everyone", "a map symbol", "a type of rhyme", "an oversimplified idea about a group of people"]'::jsonb,3,'Stereotypes overgeneralize.','original'),
('128.7.b.10.G',3,'An ad calls a pizza ''the best in the universe''. The hyperbole is meant to:','["make the claim sound exciting", "teach history", "correct a mistake", "provide exact data"]'::jsonb,0,'Hyperbole exaggerates for effect.','original'),
('128.7.b.10.G',3,'Why might a writer open an essay about teamwork with an anecdote?','["to replace evidence", "to make the idea personal and memorable", "to avoid the topic", "to confuse the reader"]'::jsonb,1,'Anecdotes draw readers in.','original'),
('128.7.b.11.A',3,'A writer plans an essay urging the city to build a skate park. The best genre choice is:','["a recipe", "a limerick about cats", "an opinion essay for city officials", "a weather chart"]'::jsonb,2,'Genre fits purpose and audience.','original'),
('128.7.b.11.A',3,'Prewriting techniques include:','["publishing, binding and printing", "erasing, folding and stapling", "copying, pasting and deleting everything", "brainstorming, outlining and freewriting"]'::jsonb,3,'Prewriting plans a draft.','original'),
('128.7.b.11.B.i',3,'A strong conclusion does which of the following?','["restates the main idea and leaves the reader with a final thought", "ends mid-idea", "introduces a new argument", "repeats every sentence"]'::jsonb,0,'Conclusions wrap up the writing.','original'),
('128.7.b.11.B.i',3,'Which transition shows contrast?','["as a result", "however", "for example", "in addition"]'::jsonb,1,'However signals a contrast.','original'),
('128.7.b.11.B.ii',4,'Depth of thought is shown when a writer:','["uses longer words only", "repeats the thesis", "explains why a fact matters", "lists facts without comment"]'::jsonb,2,'Depth means analysis, not just facts.','original'),
('128.7.b.11.B.ii',3,'Which detail is the most specific?','["It is a big telescope.", "There are things in space.", "Space things are cool.", "The Hubble Telescope has orbited Earth since 1990."]'::jsonb,3,'Specific facts add depth.','original'),
('128.7.b.11.C',3,'Replacing a vague verb like ''went'' with ''sprinted'' improves:','["word choice", "pagination", "margins", "the title"]'::jsonb,0,'Precise verbs improve word choice.','original'),
('128.7.b.11.C',3,'To avoid choppy writing, a writer can:','["start every sentence with ''The''", "combine short sentences into longer ones", "delete every adjective", "use only simple sentences"]'::jsonb,1,'Combining sentences varies sentence structure.','original'),
('128.7.b.11.D.i',3,'A comma splice can be fixed by replacing the comma with:','["a question mark", "a hyphen", "a period or a semicolon", "a second comma"]'::jsonb,2,'Separate the sentences or join them correctly.','original'),
('128.7.b.11.D.i',3,'Which of these is a run-on sentence?','["After the bell rang, everyone left.", "The bell rang, and everyone left the room.", "The bell rang. Everyone left the room.", "The bell rang everyone left the room"]'::jsonb,3,'Two complete thoughts run together without punctuation.','original'),
('128.7.b.11.D.ii',3,'What is the correct past tense of the irregular verb ''to go''?','["went", "goed", "gone", "goes"]'::jsonb,0,'Go is irregular; its past tense is went.','original'),
('128.7.b.11.D.ii',4,'What is the irregular simple past of ''tener'' for yo?','["tené", "tuve", "tení", "tenió"]'::jsonb,1,'Tener has an irregular stem in the preterite.','original'),
('128.7.b.11.D.iii',3,'Which verb agrees with the collective noun in ''The team ___ ready''?','["are", "were", "is", "be"]'::jsonb,2,'A collective noun acting as a unit takes a singular verb.','original'),
('128.7.b.11.D.iii',3,'Which is a collective noun?','["green", "run", "quickly", "flock"]'::jsonb,3,'A flock is a group of birds.','original'),
('128.7.b.11.D.iv',3,'Which adjective indicates origin?','["Mexican", "loud", "tall", "heavy"]'::jsonb,0,'Mexican tells where something is from.','original'),
('128.7.b.11.D.iv',3,'What is the superlative form of ''good''?','["most good", "best", "better", "gooder"]'::jsonb,1,'Good is irregular: good, better, best.','original'),
('128.7.b.11.D.ix',3,'Acronyms like NASA are usually written with:','["only the first letter capitalized", "no vowels", "all capital letters", "all lowercase letters"]'::jsonb,2,'Acronyms use capital letters.','original'),
('128.7.b.11.D.ix',3,'Initials in a name, such as J. R. Wells, are written:','["in lowercase with commas", "without capitals", "in italics only", "with capital letters followed by periods"]'::jsonb,3,'Initials are capitalized and punctuated.','original'),
('128.7.b.11.D.v',3,'Which is a conjunctive adverb?','["therefore", "and", "because", "although"]'::jsonb,0,'Therefore connects ideas between clauses.','original'),
('128.7.b.11.D.v',4,'A conjunctive adverb joining two independent clauses is usually preceded by:','["a question mark", "a semicolon", "an apostrophe", "a quotation mark"]'::jsonb,1,'Use a semicolon before and a comma after.','original'),
('128.7.b.11.D.vi',4,'In ''The box of pencils is on the desk'', the verb agrees with:','["desk", "pencils, not box", "box, not pencils", "the preposition of"]'::jsonb,2,'The subject is box.','original'),
('128.7.b.11.D.vi',4,'A prepositional phrase between a subject and its verb:','["always makes the verb plural", "removes the verb", "becomes the subject", "does not change which word is the subject"]'::jsonb,3,'The object of a preposition is never the subject.','original'),
('128.7.b.11.D.vii',3,'Which pronoun is reflexive?','["themselves", "they", "them", "their"]'::jsonb,0,'Reflexive pronouns end in -self or -selves.','original'),
('128.7.b.11.D.viii',3,'Words like ''since'', ''unless'' and ''while'' that start a dependent clause are called:','["prepositions", "subordinating conjunctions", "coordinating conjunctions", "interjections"]'::jsonb,1,'Subordinating conjunctions introduce dependent clauses.','original'),
('128.7.b.11.D.viii',3,'A complex sentence is formed when a subordinating conjunction joins:','["two periods", "two fragments only", "a dependent clause to an independent clause", "two titles"]'::jsonb,2,'A complex sentence has one independent and at least one dependent clause.','original'),
('128.7.b.10.D',3,'A poet writes that the sun ''waved goodbye'' at dusk. This figurative language is:','["a literal fact", "a rhyme scheme", "a number", "personification"]'::jsonb,3,'The sun is given a human action.','original'),
('128.7.b.11.D.vii',3,'In ''Nobody left early'', the word nobody is an:','["indefinite pronoun", "possessive pronoun", "reflexive pronoun", "preposition"]'::jsonb,0,'Indefinite pronouns refer to no specific person.','original'),
('128.7.b.11.D.x',3,'Titles of books are shown in print with:','["no marks", "italics or underlining", "all capitals", "bold only"]'::jsonb,1,'Book titles are italicized or underlined.','original'),
('128.7.b.11.D.x',3,'Which sentence correctly punctuates an introductory clause?','["After, the game ended we cheered.", "We cheered after, the game ended.", "After the game ended, we cheered.", "After the game, ended we cheered."]'::jsonb,2,'Use a comma after an introductory clause.','original'),
('128.7.b.11.D.xi',3,'Which spelling names a person who studies the stars?','["astronomo", "ástronomo", "astrónomó", "astrónomo"]'::jsonb,3,'Esdrújula words always carry an accent.','original'),
('128.7.b.11.D.xi',3,'Which spelling names a place where students earn degrees?','["universidad", "universidat", "universidád", "unibersidad"]'::jsonb,0,'Universidad uses v and ends in d.','original'),
('128.7.b.11.E',2,'A student finishes a report and posts it on the class website. This step is:','["drafting", "publishing", "brainstorming", "outlining"]'::jsonb,1,'Publishing shares the final copy.','original'),
('128.7.b.11.E',3,'Choosing a format for a specific audience, such as a brochure for parents, is part of:','["proofreading only", "outlining", "publishing for an appropriate audience", "ignoring the reader"]'::jsonb,2,'Publishing considers the audience.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Spanish Language Arts and English as a Second Language' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'sla_6_v1'
from (values
('128.7.b.12.A',3,'A fictional short story must include:','["a table of data", "a bibliography", "a citation", "characters, setting and a plot"]'::jsonb,3,'Fiction needs these story elements.','original'),
('128.7.b.12.A',3,'A personal narrative differs from fiction because it:','["tells about real events from the author''s life", "uses invented characters only", "has no beginning", "has no point of view"]'::jsonb,0,'Personal narratives are true accounts.','original'),
('128.7.b.12.B',3,'A thesis statement in an informational composition:','["lists the bibliography", "states the main idea about the topic", "tells a joke", "ends the paper"]'::jsonb,1,'The thesis controls the composition.','original'),
('128.7.b.12.B',3,'Which source detail would strengthen a composition on the Amazon rainforest?','["a cartoon of a cat", "the cost of a ticket", "a scientific estimate of how many species live there", "the author''s favorite color"]'::jsonb,2,'Relevant, factual details strengthen informational writing.','original'),
('128.7.b.12.C',3,'A counterclaim is:','["a conclusion", "the writer''s main idea", "a type of rhyme", "an opposing viewpoint the writer addresses"]'::jsonb,3,'Strong arguments respond to opposing views.','original'),
('128.7.b.12.C',3,'An opinion essay is stronger when the writer:','["supports each reason with evidence", "uses only feelings", "avoids facts", "repeats the opinion without reasons"]'::jsonb,0,'Evidence strengthens reasons.','original'),
('128.7.b.12.D',3,'A letter requesting information should begin with:','["a joke about the weather", "a greeting and a clear statement of purpose", "a list of complaints", "the closing"]'::jsonb,1,'Request letters state the purpose early.','original'),
('128.7.b.12.D',2,'In a formal request letter, the closing might be:','["See ya,", "Whatever,", "Sincerely,", "Later,"]'::jsonb,2,'Formal letters use a polite closing.','original'),
('128.7.b.13.A',3,'A researcher clarifies a broad question like ''Tell me about space'' by:','["adding more topics", "deleting it", "making it vaguer", "narrowing it to a specific focus"]'::jsonb,3,'Clarifying makes a question researchable.','original'),
('128.7.b.13.A',3,'Formal inquiry differs from informal inquiry because it:','["follows a planned process and uses documented sources", "has no questions", "uses no sources", "relies on guessing"]'::jsonb,0,'Formal inquiry is structured.','original'),
('128.7.b.13.B',3,'Following a research plan helps a student:','["avoid sources", "stay organized and meet deadlines", "skip steps", "write without notes"]'::jsonb,1,'Plans keep research on track.','original'),
('128.7.b.13.B',3,'A research plan made with adult help might include:','["a joke list", "a lunch menu", "a timeline, a source list and check-in dates", "a seating chart"]'::jsonb,2,'Plans organize time and sources.','original'),
('128.7.b.13.C',3,'A variety of sources for a report might include:','["only the cover of a book", "three copies of the same page", "only social media posts", "a book, an interview and a reliable website"]'::jsonb,3,'Different types of sources give a fuller picture.','original'),
('128.7.b.13.C',3,'To gather relevant information efficiently, a researcher can use:','["keywords and an index", "the cover image", "random page flipping", "guessing page numbers"]'::jsonb,0,'Keywords and indexes lead to relevant information.','original'),
('128.7.b.13.D',3,'Which source is most credible for information about a medical topic?','["a friend''s opinion", "a published article by a doctor at a medical school", "a rumor shared online", "an anonymous blog"]'::jsonb,1,'Credible sources have expert authors.','original'),
('128.7.b.13.D',3,'Credibility of a source is higher when the author:','["gives no sources", "only shares opinions", "is an expert and cites evidence", "is unknown"]'::jsonb,2,'Expertise and evidence build credibility.','original'),
('128.7.b.13.E',3,'Which shows understanding of information gathered?','["listing page numbers", "copying the first paragraph", "writing only the title", "explaining the main points in a written summary"]'::jsonb,3,'A summary shows understanding.','original'),
('128.7.b.13.E',3,'A graphic organizer can show understanding by:','["organizing facts into categories", "deleting the notes", "mixing the topics", "hiding the facts"]'::jsonb,0,'Organizers sort ideas.','original'),
('128.7.b.13.F',3,'Which is an example of paraphrasing?','["Copying a sentence without quotation marks", "Rewriting an idea in your own words and citing the source", "Copying the entire article", "Changing only the author''s name"]'::jsonb,1,'Paraphrasing restates ideas with credit.','original'),
('128.7.b.13.F',3,'Plagiarism is a problem because it:','["improves originality", "gives credit to the author", "presents someone else''s work as your own", "makes writing shorter"]'::jsonb,2,'Plagiarism is dishonest.','original'),
('128.7.b.13.G',3,'A bibliography entry usually includes the author, title and:','["a joke", "a drawing", "the reader''s name", "publication information"]'::jsonb,3,'Publication details help locate the source.','original'),
('128.7.b.13.G',3,'Why do researchers include a bibliography?','["so readers can find the sources", "to make the paper look longer", "to list their friends", "to hide sources"]'::jsonb,0,'A bibliography credits and locates sources.','original'),
('128.7.b.13.H',3,'A student chooses a podcast to deliver research. This is an:','["written mode of delivery", "oral mode of delivery", "unrelated mode of delivery", "silent mode of delivery"]'::jsonb,1,'A podcast is spoken.','original'),
('128.7.b.13.H',3,'Which delivery combines more than one mode?','["a spoken message only", "a printed page only", "a video with narration and text", "a handwritten note"]'::jsonb,2,'Multimodal delivery blends modes.','original'),
('128.7.b.2.A.i',3,'Which word is aguda?','["teléfono", "mesa", "árbol", "canción"]'::jsonb,3,'Canción is stressed on the last syllable.','original'),
('128.7.b.2.A.i',4,'In the word cómpraselo, the stress is on the:','["syllable before the third-to-last", "third-to-last syllable", "next-to-last syllable", "last syllable"]'::jsonb,0,'Sobresdrújulas are stressed before the antepenultimate syllable.','original'),
('128.7.b.2.A.ii',3,'How many syllables does the word sueño have?','["1", "2", "3", "4"]'::jsonb,1,'Sue-ño: ue is a diphthong.','original'),
('128.7.b.2.A.ii',3,'Two weak vowels together, as in ui in the word cuidado, form:','["a consonant blend", "a hiatus", "a diphthong", "a prefix"]'::jsonb,2,'Weak vowels combine into one syllable.','original'),
('128.7.b.2.A.iii',3,'Which word with an accent means ''more''?','["màs", "mâs", "mas", "más"]'::jsonb,3,'Más with an accent means more.','original'),
('128.7.b.2.A.iii',3,'Tú and tu differ because:','["tú means you and tu means your", "they have different syllable counts", "they are both verbs", "the accent changes the sound of t"]'::jsonb,0,'A diacritical accent changes meaning.','original'),
('128.7.b.2.A.iv',3,'The prefix anti- in the word antibiótico means:','["under", "against", "with", "before"]'::jsonb,1,'Anti- means against.','original'),
('128.7.b.2.A.iv',3,'The prefix super- in the word supermercado means:','["without", "again", "above or very large", "below"]'::jsonb,2,'Super- means over or beyond.','original'),
('128.7.b.2.B.i',3,'Which spelling of the word meaning ''now'' uses h correctly?','["aora", "ahóra", "ahorra", "ahora"]'::jsonb,3,'Ahora begins with a silent h.','original'),
('128.7.b.2.B.i',3,'Which word is spelled with v?','["nuevo", "nuevó", "nuebo", "nueyo"]'::jsonb,0,'Nuevo uses v.','original'),
('128.7.b.2.B.ii',3,'Which spelling of the word for ''also'' has the correct accent for a word stressed on the last syllable and ending in n?','["tambien", "también", "támbien", "tambíen"]'::jsonb,1,'Aguda words ending in n carry an accent.','original'),
('128.7.b.2.B.ii',3,'Which spelling is a grave word ending in a consonant other than n or s?','["arbóll", "arbol", "árbol", "arból"]'::jsonb,2,'Graves ending in other consonants take an accent.','original'),
('128.7.b.2.B.iii',4,'Which spelling is a correct sobresdrújula?','["digámelo", "digaméló", "digamelo", "dígamelo"]'::jsonb,3,'Sobresdrújulas always carry a written accent.','original'),
('128.7.b.2.B.iii',3,'Sobresdrújulas always carry:','["a written accent", "no accent", "two accents", "a hyphen"]'::jsonb,0,'Stress before the antepenultimate syllable is always marked.','original'),
('128.7.b.2.B.iv',3,'Which spelling shows a hiatus in a girl''s name?','["Marìa", "María", "Maria", "Mária"]'::jsonb,1,'The accent on í separates the vowels.','original'),
('128.7.b.2.B.iv',3,'Which spelling shows a diphthong without an accent?','["ciúdad", "ciudád", "ciudad", "cíudad"]'::jsonb,2,'Iu forms a diphthong; no accent is needed.','original'),
('128.7.b.2.B.v',3,'Which spelling is correct for ''you ate'' (tú, comer, simple past)?','["comíste", "comistè", "cómiste", "comiste"]'::jsonb,3,'The tú form of the simple past needs no accent here.','original'),
('128.7.b.2.B.v',3,'Which spelling is correct for ''I will sing''?','["cantaré", "cantare", "cantarê", "cántare"]'::jsonb,0,'Future yo forms carry an accent on the final é.','original'),
('128.7.b.2.C',2,'Cursive writing for a long assignment should stay:','["tiny at the end", "consistent and readable", "different each line", "messy to save time"]'::jsonb,1,'Legible writing aids communication.','original'),
('128.7.b.2.C',2,'Which habit improves cursive legibility?','["skipping loops", "rushing each word", "keeping letters evenly sloped and sized", "pressing as hard as possible"]'::jsonb,2,'Consistency improves legibility.','original'),
('128.7.b.3.A',3,'Which resource would show a word''s origin?','["a map", "a ruler", "a calendar", "a dictionary entry"]'::jsonb,3,'Dictionaries often include etymology.','original'),
('128.7.b.3.A',3,'A thesaurus is used to find:','["synonyms", "pronunciation only", "page numbers", "maps"]'::jsonb,0,'A thesaurus lists words with similar meanings.','original'),
('128.7.b.3.B',3,'To determine the meaning of an unfamiliar word you can use:','["the book''s color", "clues in the sentences nearby", "the font", "its page number"]'::jsonb,1,'Context beyond a sentence reveals meaning.','original'),
('128.7.b.3.B',3,'The sentence ''Her actions were benevolent; she donated food every week'' suggests benevolent means:','["lazy", "cruel", "kind and generous", "confused"]'::jsonb,2,'Donating food shows kindness.','original'),
('128.7.b.3.C',3,'The prefix trans- in the word transatlántico means:','["before", "not", "under", "across"]'::jsonb,3,'Trans- means across or beyond.','original'),
('128.7.b.3.C',3,'The prefix semi- in the word semicírculo means:','["half", "double", "none", "many"]'::jsonb,0,'Semi- means half.','original'),
('128.7.b.3.D',3,'An adage is:','["a math rule", "a short saying that expresses a common truth", "a long story", "a type of rhyme"]'::jsonb,1,'Adages are traditional sayings.','original'),
('128.7.b.3.D',3,'A pun is:','["a list of facts", "a rule of grammar", "a joke that plays on word meanings or sounds", "a type of map"]'::jsonb,2,'Puns use wordplay.','original'),
('128.7.b.3.E',3,'Sino and si no are commonly confused because they:','["are spelled the same", "are both verbs", "have the same meaning", "sound alike but have different meanings"]'::jsonb,3,'Sound-alike terms need careful spelling.','original'),
('128.7.b.3.E',3,'Homographs such as ''live'' (to reside) and ''live'' (alive) differ in:','["pronunciation and meaning", "spelling only", "number of letters", "nothing"]'::jsonb,0,'Homographs share spelling but not meaning or sometimes sound.','original'),
('128.7.b.4',2,'Strong readers often improve their writing because:','["they are unrelated", "reading and writing skills build on each other", "only listening helps", "writing hurts reading"]'::jsonb,1,'Language skills support each other.','original')
